// Reference solution
function roundRobin(instances, n, down = []) {
  const up = instances.filter((x) => !down.includes(x));
  const out = [];
  let i = 0;
  for (let k = 0; k < n; k++) {
    if (up.length === 0) { out.push(null); continue; }
    out.push(up[i % up.length]);
    i++;
  }
  return out;
}

